package com.example.ptt.crypto

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/** Every vector in testdata/protocol-vectors.json, generated by the Go server module. */
class ProtocolVectorsTest {
    private fun b64(v: JsonValue.Obj, key: String) = VectorFile.b64(v, key)

    @Test
    fun signedObjects() {
        val vectors = VectorFile.section("signed")
        assertTrue(vectors.size > 10)
        for (v in vectors) {
            val name = v.string("name")
            val pub = b64(v, "public")
            val outcome = try {
                val obj = SignedObject.fromWire(v.string("wire"))
                val msg = SignedObject.message(v.string("ctx"), obj.payload)
                if (TinkKeys.verifyEd25519(pub, msg, obj.sig)) "valid" else "bad_signature"
            } catch (_: ProtocolException) {
                "malformed"
            }
            assertEquals(name, v.string("expect"), outcome)
            if (outcome == "valid") {
                val keys = DeviceKeys.create(
                    InMemoryDeviceKeyStore(presetSigning = InMemoryDeviceKeyStore.ed25519FromSeed(b64(v, "seed"), pub))
                )
                assertArrayEquals(name, pub, keys.ed25519Public)
                val obj = SignedObject.fromWire(v.string("wire"))
                assertArrayEquals("$name: same signature", b64(v, "sig"), keys.sign(v.string("ctx"), b64(v, "payload")))
                assertEquals("$name: same wire", v.string("wire"), obj.toWire())
            }
        }
    }

    @Test
    fun rosterPayloads() {
        val vectors = VectorFile.section("rosters")
        assertTrue(vectors.size > 50)
        val reencoded = setOf("family", "single-admin-bootstrap", "unicode-names")
        for (v in vectors) {
            val name = v.string("name")
            val payload = b64(v, "payload")
            if (v.string("expect") == "invalid") {
                try {
                    Roster.parse(payload)
                    fail("$name: accepted")
                } catch (_: ProtocolException) {
                    continue
                }
            }
            val roster = Roster.parse(payload)
            assertEquals(name, v.number("version"), roster.version)
            assertEquals(name, v.number("issued_at"), roster.issuedAt)
            val expected = v.array("devices").map { it.asObject("device") }
            assertEquals(name, expected.size, roster.devices.size)
            expected.zip(roster.devices).forEach { (e, d) ->
                assertEquals(name, e.string("id"), d.id)
                assertEquals(name, e.string("user_id"), d.userId)
                assertEquals(name, e.string("display_name"), d.displayName)
                assertEquals(name, e.string("device_name"), d.deviceName)
                assertEquals(name, e.bool("admin"), d.admin)
                assertArrayEquals(name, b64(e, "ed25519"), d.ed25519)
                assertArrayEquals(name, b64(e, "x25519"), d.x25519)
            }
            if (name in reencoded) assertArrayEquals("$name: re-encoding", payload, roster.encodePayload())
        }
    }

    @Test
    fun enrollmentMacs() {
        for (v in VectorFile.section("enrollment_macs")) {
            val name = v.string("name")
            val secret = b64(v, "secret")
            val code = b64(v, "code")
            val deviceId = v.string("device_id")
            val ed = b64(v, "ed25519")
            val x = b64(v, "x25519")
            val mac = b64(v, "mac")
            val computed = EnrollmentMac.compute(secret, code, deviceId, ed, x)
            assertEquals(name, v.bool("expect_valid"), computed.contentEquals(mac))
            assertEquals(name, v.bool("expect_valid"), EnrollmentMac.verify(secret, code, deviceId, ed, x, mac))
        }
    }

    @Test
    fun qrText() {
        val vectors = VectorFile.section("qrs")
        assertTrue(vectors.size >= 3)
        for (v in vectors) {
            val name = v.string("name")
            val secret = v.members["secret"]?.let { b64(v, "secret") }
            val admins = (v.members["admins"] as? JsonValue.Arr)?.items.orEmpty().map {
                val a = it.asObject("admin")
                TrustedAdmin(a.string("id"), b64(a, "ed25519"))
            }
            val qr = EnrollmentQr(v.string("url"), b64(v, "code"), secret, admins)
            assertEquals(name, v.string("text"), qr.encode())
            val parsed = EnrollmentQr.parse(v.string("text"))
            assertEquals(name, v.string("url"), parsed.url)
            assertArrayEquals(name, qr.code, parsed.code)
            assertEquals(name, secret == null, parsed.isBootstrap)
            assertEquals(name, admins.map { it.id }, parsed.admins.map { it.id })
        }
    }

    @Test
    fun hpkeWrapsFromGoOpenWithTink() {
        val vectors = VectorFile.section("hpke")
        assertTrue(vectors.isNotEmpty())
        for (v in vectors) {
            val name = v.string("name")
            val info = PageEnvelopes.info(v.string("page_id"), v.string("session_id"), v.string("device_id"))
            assertArrayEquals(name, b64(v, "info"), info)
            val keys = DeviceKeys.create(
                InMemoryDeviceKeyStore(
                    presetHpke = InMemoryDeviceKeyStore.hpkeFromRaw(
                        b64(v, "recipient_private"),
                        b64(v, "recipient_public")
                    )
                )
            )
            assertArrayEquals(name, b64(v, "recipient_public"), keys.x25519Public)
            val wrapped = b64(v, "wrapped")
            assertEquals(80, wrapped.size)
            assertArrayEquals(name, b64(v, "session_key"), keys.unwrap(wrapped, info))
            // Wrong info (another device) must not open.
            val other = PageEnvelopes.info(
                v.string("page_id"),
                v.string("session_id"),
                "00000000-0000-4000-8000-000000000000"
            )
            try {
                keys.unwrap(wrapped, other)
                fail("$name: opened with the wrong info")
            } catch (_: ProtocolException) {
                // expected
            }
            // Kotlin's own wrap to the same key opens too.
            val mine = TinkKeys.hpkeEncrypter(keys.x25519Public).encrypt(b64(v, "session_key"), info)
            assertArrayEquals(name, b64(v, "session_key"), keys.unwrap(mine, info))
        }
    }

    @Test
    fun envelopePayloads() {
        val vectors = VectorFile.section("envelope_payloads")
        assertTrue(vectors.size > 30)
        for (v in vectors) {
            val name = v.string("name")
            val payload = b64(v, "payload")
            if (v.string("expect") == "invalid") {
                try {
                    EnvelopePayload.parse(payload)
                    fail("$name: accepted")
                } catch (_: ProtocolException) {
                    continue
                }
            }
            val e = EnvelopePayload.parse(payload)
            assertEquals(name, v.string("page_id"), e.pageId)
            assertEquals(name, v.string("level"), e.level)
            assertEquals(name, v.string("from_device"), e.fromDevice)
            assertEquals(name, v.string("to_user"), e.toUser)
            assertEquals(name, v.number("created_at"), e.createdAt)
            assertEquals(name, v.array("keys").map { (it as JsonValue.Str).value }, e.keys.keys.sorted())
        }
    }

    @Test
    fun envelopeReceive() {
        val vectors = VectorFile.section("envelope_receive")
        assertTrue(vectors.size >= 10)
        for (v in vectors) {
            val name = v.string("name")
            val roster = Roster.parse(b64(v, "roster_payload"))
            val self = roster.find(v.string("receiver_device_id"))!!
            val keys = DeviceKeys.create(
                InMemoryDeviceKeyStore(
                    presetHpke = InMemoryDeviceKeyStore.hpkeFromRaw(b64(v, "receiver_private"), self.x25519)
                )
            )
            val obj = SignedObject.fromWire(v.string("wire"))
            val push = PagePush(v.string("push_page_id"), v.string("push_level"), v.string("push_from_user"))
            val result = PageEnvelopes.receive(roster, self.id, keys, obj, push)
            if (v.string("expect") == "ok") {
                assertTrue("$name: dropped", result is ReceiveResult.Accepted)
                assertArrayEquals(name, b64(v, "session_key"), (result as ReceiveResult.Accepted).sessionKey)
            } else {
                assertTrue("$name: accepted", result is ReceiveResult.Dropped)
                assertEquals(name, v.string("reason"), reasonName((result as ReceiveResult.Dropped).reason))
            }
        }
    }

    private fun reasonName(r: DropReason): String = r.name.lowercase()

    @Test
    fun rosterAcceptance() {
        val vectors = VectorFile.section("roster_accept")
        assertTrue(vectors.size >= 25)
        for (v in vectors) {
            val name = v.string("name")
            val current = v.members["current"]?.let { Roster.parse(b64(v, "current")) }
            val trusted = (v.members["trusted_admins"] as? JsonValue.Arr)?.items.orEmpty().map {
                val a = it.asObject("admin")
                TrustedAdmin(a.string("id"), b64(a, "ed25519"))
            }
            val self = (v.members["self"] as? JsonValue.Obj)?.let {
                DeviceIdentity(it.string("device_id"), b64(it, "ed25519"), b64(it, "x25519"))
            }
            val decision = try {
                RosterVerifier.accept(current, trusted, self, SignedObject.fromWire(v.string("wire")))
            } catch (_: ProtocolException) {
                null
            }
            when (v.string("expect")) {
                "accept" -> assertTrue("$name: rejected", decision is RosterDecision.Accepted)

                else -> {
                    val reason = if (decision == null) {
                        "malformed_wire"
                    } else {
                        assertTrue("$name: accepted", decision is RosterDecision.Rejected)
                        (decision as RosterDecision.Rejected).reason.name.lowercase()
                    }
                    assertEquals(name, v.string("reason"), reason)
                }
            }
        }
    }

    @Test
    fun kotlinRejectsMalformedSignedWireJson() {
        // Duplicate, case-variant and unknown keys in the signed-object wrapper itself.
        val ok = VectorFile.section("signed").first { it.string("expect") == "valid" }.string("wire")
        SignedObject.fromWire(ok)
        assertFalse(ok.contains("Payload"))
        for (bad in listOf(
            ok.replaceFirst("\"signer\"", "\"Signer\""),
            ok.replaceFirst("{", "{\"sig\":\"x\","),
            ok.replaceFirst("}", ",\"extra\":1}"),
            ok + "x"
        )) {
            try {
                SignedObject.fromWire(bad)
                fail("accepted $bad")
            } catch (_: ProtocolException) {
                // expected
            }
        }
    }
}
